/* =Global
----------------------------------------------- */
body {
	border-top: 3px solid #333333;
	background: #ffffff;
	font-family: 'Merriweather', serif;
}

h1, h2, h3, h4, h5, h6 {
	font-weight: 700;
}

h1, h2, h3, h4, h5, h6, .entry-title a,
.site-contentpbt .site-navigationpbt a {
	font-family: 'Merriweather', serif;
	line-height: 1.4;
}

a {
	color: #0099cc;
	-webkit-transition:color 0.23s ease-in;  
	-moz-transition:color 0.23s ease-in;  
	-o-transition:color 0.23s ease-in;  
	transition:color 0.23s ease-in; 
}	

a:hover {
	color: #333333;
}	

table {
	width: 100%;
}

table th {
	color: #333333;
	padding: 9px 10px;
}

table .label {
	background: none;
	padding: 9px 10px;
	font-size: inherit;
	line-height: 1.6;
	font-weight: normal;
	display: inline-block;
}

.clear {
	clear: both;
	display: block;
	font-size: 0;
	height: 0;
	line-height: 0;
	width:100%;
}

ul, ol, dl {
	margin-left: 30px;
}

blockquote {
	font-style: italic;
	padding: 20px 30px;
	background: #fcfcfc;
	border-left: 5px solid #eee;
}

.main-navigationpbt,
.border-radius-small {
	-webkit-border-radius: 3px;
	-moz-border-radius: 3px;
	border-radius: 3px;
}

.border-radius-circle {
	-webkit-border-radius: 50%;
	-moz-border-radius: 50%;
	border-radius: 50%;
}

#submit-comment,
input[type="submit"] {
	width: auto;
	background: #43bdef;
	border: 1px solid #129bd4;
	color: white;
	cursor: pointer;
	display: inline-block;
	font-family: inherit;
	font-size: 16px;
	line-height: 1;
	margin: 0;
	padding: 10px 20px 11px;
	position: relative;
	text-align: center;
	text-decoration: none;
	-webkit-box-shadow: 0 1px 0 rgba(255,255,255,0.5) inset;
	-moz-box-shadow: 0 1px 0 rgba(255,255,255,0.5) inset;
	box-shadow: 0 1px 0 rgba(255,255,255,0.5) inset;
	-webkit-transition: background-color 0.15s ease-in-out;
	-moz-transition: background-color 0.15s ease-in-out;
	-o-transition: background-color 0.15s ease-in-out;
	transition: background-color 0.15s ease-in-out;
}

#submit-comment:hover,
input[type="submit"]:hover {
	background-color: #14aceb;
}

#gotoppbt {
	position: fixed;
	bottom: 0;
	right: 0;
	cursor: pointer;
	display: none;
	z-index: 99;
}

#gotoppbt h6 {
	margin: 0;
	padding: 13px 23px;
	color: #333333;
}

@media (max-width: 979px) { 
	#gotoppbt { 
		right: 0;
		width: 100%;
		background: #ffffff;
	}
}

/* Alignment */
.alignleft {
	display: inline;
	float: left;
	margin-right: 1.5em;
}
.alignright {
	display: inline;
	float: right;
	margin-left: 1.5em;
}
.aligncenter {
	clear: both;
	display: block;
	margin: 0 auto 15px;
}

/* Text meant only for screen readers */
.assistive-text {
	clip: rect(1px 1px 1px 1px); /* IE6, IE7 */
	clip: rect(1px, 1px, 1px, 1px);
	position: absolute !important;
}

/* =Header
----------------------------------------------- */
#mastheadpbt {
	text-align: center;
}

#mastheadpbt .brandpbt {
	margin-top: 30px;
	margin-bottom: 30px;
}

#mastheadpbt .website-logo {
	margin-top: 25px;
	margin-bottom: 35px;
}

#mastheadpbt .brandpbt h1 a {
	color: #333333;
}

#mastheadpbt .brandpbt h1 a:hover {
	color: #0099cc;
}

#mastheadpbt .brandpbt h2{
	margin-top: -10px;
	font-size: 22px;
	font-family: 'Lora', serif;
	color: #acacac;
	font-weight: 300;
}

/* =Menu
----------------------------------------------- */
.main-navigationpbt { 
	border-top: 1px solid #f8f8f8;
	border-bottom: 1px solid #f8f8f8;
	margin-bottom: 60px;
}

.main-navigationpbt ul,
.nav-barpbt li ul {
	list-style: none;
	margin: 0;
}

.main-navigationpbt ul {
	padding: 10px 0;
	background: none;
	height: auto;
}

.main-navigationpbt .nav-barpbt li { 
	border: none; 
	float: none;
	display: inline-block;
}

.main-navigationpbt .nav-barpbt li a:hover {
	color: #0099cc;
}

.main-navigationpbt .nav-barpbt li a {
	color: #333333;
}

.nav-barpbt > li:hover {
	color: #111;
	background: none;
}

.main-navigationpbt .nav-barpbt li .sub-menu li.current-menu-item a:hover,
.main-navigationpbt .nav-barpbt li .children li a,
.main-navigationpbt .nav-barpbt li .sub-menu li a {
	padding: 20px 14px;
	background: #fdfdfd;
}

.main-navigationpbt ul ul {
	-moz-box-shadow: 0 1px 1px rgba(0,0,0,0.2);
	-webkit-box-shadow: 0 1px 1px rgba(0,0,0,0.2);
	box-shadow: 0 1px 1px rgba(0,0,0,0.2);
	display: none;
	float: left;
	position: absolute;
	top: 2.4em;
	left: 0;
	z-index: 99999;
}

.main-navigationpbt ul ul ul {
	left: 100%;
	top: 0;
}

.main-navigationpbt ul ul a {
	width: 200px;
}

.main-navigationpbt ul li:hover > ul {
	display: block;
}

.nav-barpbt li ul li {
	border: none;
}

/* Small menu */
.menu-toggle {
	cursor: pointer;
	background: #5db1f5;
	color: #ffffff;
	border-bottom: 1px solid #e5e5e5;
	text-align: center;
	margin-bottom: -20px;
	padding-top: 15px;
	padding-bottom: 10px;
}

.main-small-navigation {
	margin-bottom: 30px;
}

.main-small-navigation .menu {
	display: none;
}

.main-small-navigation .nav-barpbt > li {
	border-bottom: 1px solid #565656;
}

.main-small-navigation .nav-barpbt li a {
	padding: 10px 14px;
}

.main-small-navigation .nav-barpbt .sub-menu li a {
	padding: 20px 14px;
}

.main-small-navigation li {
	border: none;
}

/* =Content
----------------------------------------------- */
.sep {
	margin: 0 5px;
}

.entry-header {
	text-align: center;
	margin-bottom: 30px;
}

.entry-header .entry-title a{
	color: #333333;
}

.entry-header .entry-title a:hover {
	color: #0099cc;
}

.entry-meta {
	color: #bcbcbc;
	clear: both;
}

.entry-meta .entry-date {
	color: #333333;
}

.entry-meta.top {
	margin-bottom: 20px;
}

.entry-meta.bottom {
	padding: 10px;
	margin-top: 15px;
	margin-bottom: 20px;
	text-align: center;
}

.entry-meta.bottom a,
.entry-meta.bottom span {
	line-height: 1.6;
}

.post-seperator {
	margin: 0 auto 60px;
	border-bottom: 2px dotted #f2f2f2;
	width: 40%;
}

.sticky-post {
	padding: 30px;
	background: #F9F4A8;
	border: 1px solid #e0db98;
}

.sticky-post .entry-meta {
	color: #323232;
}

.sticky-post a {
	color: #67675C;
}

.sticky-post a:hover {
	color: #9e9e70;
}

.sticky-post .entry-meta.bottom {
	padding: 0;
}

.sticky-post .post-seperator {
	margin: 0 auto 30px;
	border-bottom: 2px dotted #e0db98;
	width: 40%;
}

.hentry {
	padding-left: 30px;
	padding-right: 30px;
	margin: 0 0 1.5em;
}

.single .byline,
.group-blog .byline {
	display: inline;
}

.entry-content,
.entry-summary {
	margin: 1.5em 0 0;
	overflow: hidden;
	line-height: 1.6;
}

/* =Asides
----------------------------------------------- */

.blog .format-aside .entry-title,
.archive .format-aside .entry-title {
}


/* =Media
----------------------------------------------- */
/* Make sure embeds and iframes fit their containers */
embed,
iframe,
object {
	max-width: 100%;
}

/* =Widgets
----------------------------------------------- */
.sidebar-buttonpbt {
	padding: 20px;
	position: fixed;
	top: 0;
	right: 0;
	color: #000;
	cursor: pointer;
	z-index: 101;
}

.widget-areapbt {
	background: #333333;
	border-left: 1px solid #555555;
	position: fixed;
	top: 0;
	right: -20px;
	padding-right: 20px;
	overflow:auto;
	z-index: 100;
}

.widget-innerpbt {
	width: 0px;
	display: none;
}

#secondarypbt .widget-title {
	color: #eee;
	text-align: center;
	font-size: 24px;
}

#secondarypbt .widget h2 {
	color: #eee;
	text-align: center;
	font-size: 24px;
}

#secondarypbt .widget {
	display: none;
	color: #afb5b4;
	padding-right: 30px;
	padding-left: 30px;
	padding-bottom: 30px;
	border-bottom: 1px solid #434343;
	position: relative;
	font-style: normal;
	font-size: 16px;
	line-height: 1.65;
}

#secondarypbt .widget:before {
    content: "";
	border-bottom: 1px solid #353535;
	position: absolute;
	bottom: 0;
	left: 0;
	width: 100%;
}

#secondarypbt .widget p {
	font-style: normal;
	font-size: 16px;
	line-height: 1.65;
}

#secondarypbt .widget a {
	color: #fff;
}

#secondarypbt .widget a:hover {
	color: #09C;
}

/* Make sure select elements fit in widgets */
.widget select {
	max-width: 100%;
}

/* Search widget */
#searchsubmit {
	display: none;
}

/* =Footer
----------------------------------------------- */
.site-footerpbt {
	margin-top: 30px;
	margin-bottom: 60px;
	color: #ccc;
	text-align: center;
	line-height: 1.6;
}

.site-footerpbt a {
	color: #aaa;
}

.site-footerpbt a:hover {
	color: #2BA6CB;
}

#pagepbt .toggle-box {
	margin-bottom: 30px;
}

#pagepbt .toggle-container {
	border: 1px solid #f8f8f8;
}

#pagepbt .toggle-container .title,
#pagepbt .toggle-container .content  {
	padding: 15px;
}

#pagepbt .toggle-container .title h5 {
	margin: 0;
	cursor: pointer;
}

#pagepbt .toggle-container .content {
	background: #ffffff;
	color: #191919;
	display: none;
}

#pagepbt .alert-box {
	padding: 20px 20px 5px 20px;
}

.site-title {
  font-size:52px;
}

h2.date-header {
  margin: 10px 0px;
  display: none;
}

.main .widget {
  margin: 0 0 5px;
  padding: 0 0 2px;
}

.main .Blog {
  border-bottom-width: 0;
}

#header .description {
  color:#ffffff;
  font-size:14px;
  text-shadow:0px 1px 0px #000000;
}

/* Comments----------------------------------------------- */
#comments {
	padding:10px;
	margin-bottom:20px;
}

#comments h4 {
    font-size:22px;
    margin-bottom:10px;
}

.deleted-comment {
  font-style: italic;
  color: gray;
}

#blog-pager-newer-link {
  float: left;
}

#blog-pager-older-link {
  float: right;
}

#blog-pager {
  text-align: center;
  padding:5px;
}

.feed-links {
  clear: both;
}

.comment-form {
}

#navbar-iframe {
  height: 0;
  visibility: hidden;
  display: none;
}

.separator a[style="margin-left: 1em; margin-right: 1em;"] {margin-left: auto!important;margin-right: auto!important;}

.PopularPosts .widget-content ul li {
  padding:6px 0px;
}

.reaction-buttons table{
  border:none;
  margin-bottom:5px;
}

.reaction-buttons table, .reaction-buttons td{
  border:none !important;
}

